<?php require 'config.php';require_login();if(!admin()){http_response_code(403);exit('Access denied');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'&&$id){$stmt=$pdo->prepare('UPDATE tours SET active=0 WHERE id=?');$stmt->execute([$id]);flash('Tour hidden.');go('admin.php');}if($action==='save'){$title=trim($_POST['title']??'');$location=trim($_POST['location']??'');$description=trim($_POST['description']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);if(!$title||!$location||!$description||$price===false||$price<0||!$capacity||$capacity<1){$error='Please fill all fields correctly.';}else{if($id){$stmt=$pdo->prepare('UPDATE tours SET title=?,location=?,description=?,price=?,capacity=? WHERE id=?');$stmt->execute([$title,$location,$description,$price,$capacity,$id]);}else{$stmt=$pdo->prepare('INSERT INTO tours(title,location,description,price,capacity,active) VALUES(?,?,?,?,?,1)');$stmt->execute([$title,$location,$description,$price,$capacity]);}flash('Tour saved.');go('admin.php');}}}$edit=null;if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM tours WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$tours=$pdo->query('SELECT * FROM tours WHERE active=1 ORDER BY id DESC')->fetchAll();require 'header.php';?><section class="page-head"><h1>Manage Tours</h1><p>Admin access only.</p></section><div class="formbox"><h2><?=$edit?'Edit Tour':'Add Tour'?></h2><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Title<input required name="title" value="<?=e($edit['title']??'')?>"></label><label>Location<input required name="location" value="<?=e($edit['location']??'')?>"></label><label>Description<textarea required name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><label>Price (SAR)<input required type="number" min="0" step="0.01" name="price" value="<?=e($edit['price']??'')?>"></label><label>Capacity per date<input required type="number" min="1" name="capacity" value="<?=e($edit['capacity']??'')?>"></label><button class="btn">Save Tour</button></form></div><div class="panel"><h2>Current Tours</h2><div class="tablewrap"><table><thead><tr><th>Title</th><th>Location</th><th>Price</th><th>Action</th></tr></thead><tbody><?php foreach($tours as $t):?><tr><td><?=e($t['title'])?></td><td><?=e($t['location'])?></td><td><?=e($t['price'])?> SAR</td><td><a href="admin.php?edit=<?=$t['id']?>">Edit</a> <form method="post" class="inline" onsubmit="return confirm('Hide this tour?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="smallbtn">Hide</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php';?>